package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes: the original implementation scanned the input one
// character at a time while juggling several pieces of ad-hoc state (the
// header level, a list counter, a "list opened" flag and a "header
// entered" flag). It also re-interpreted '#' and '*' markers that appeared
// in the middle of a line, which made the control flow very hard to follow.
//
// The rewrite works line by line, which matches how markdown is actually
// structured:
//
//  1. emphasis markers (__bold__ / _italic_) are resolved up front, on the
//     whole document, exactly as the original implementation did;
//  2. every line is classified as a header, a list item or a paragraph;
//  3. the resulting HTML fragments are joined together, closing an open
//     <ul> as soon as a non-list line (or the end of the input) follows it.
//
// With this structure each block type has a single, obvious code path and
// there is no character-level state to track.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var html strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		switch {
		case line == "":
			// A blank line ends any open block but produces no HTML of its own.
			closeList(&html, &inList)
		case headerLevel(line) > 0:
			closeList(&html, &inList)
			html.WriteString(renderHeader(line))
		case isListItem(line):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + renderListItem(line) + "</li>")
		default:
			closeList(&html, &inList)
			html.WriteString("<p>" + line + "</p>")
		}
	}
	closeList(&html, &inList)
	return html.String()
}

// applyEmphasis resolves the first bold (__text__) and first italic (_text_)
// pair in the document. The original implementation performed exactly these
// four single replacements on the whole input before parsing it, so the
// order matters: strong is resolved before em.
func applyEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)
	return markdown
}

// headerLevel returns the level (1-6) if line is a markdown header, that is
// a line starting with 1 to 6 '#' characters followed by a space.
// Seven or more '#' are not a valid header level, so such lines are treated
// as ordinary paragraphs.
func headerLevel(line string) int {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 || level > 6 || level == len(line) || line[level] != ' ' {
		return 0
	}
	return level
}

// renderHeader renders a header line as <hN>text</hN>. The header text is
// everything after the '#'s and the space that separates them from the text;
// anything else on the line (including further '#' or '*' characters) is
// kept verbatim and not re-interpreted as markdown.
func renderHeader(line string) string {
	level := headerLevel(line)
	text := strings.TrimPrefix(line, strings.Repeat("#", level))
	text = strings.TrimPrefix(text, " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, text, level)
}

// isListItem reports whether line is an unordered list item ("* item").
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

// renderListItem renders a list item line, dropping the "* " marker.
// The item text is kept verbatim and not re-interpreted as markdown.
func renderListItem(line string) string {
	return strings.TrimPrefix(line, "* ")
}

// closeList terminates an open <ul> block, if any.
func closeList(html *strings.Builder, inList *bool) {
	if *inList {
		html.WriteString("</ul>")
		*inList = false
	}
}

